const body = $input.first().json.body || $input.first().json;
const allowed = ['CLICK','ORDER','SALE','COMMISSION','CANCELLED','RETURNED'];
const eventType = String(body.event_type || '').toUpperCase();
if (!allowed.includes(eventType)) {
  throw new Error('event_type inválido: ' + eventType);
}
return [{
  json: {
    product_id: body.product_id ?? null,
    publication_id: body.publication_id ?? null,
    source: body.source ?? null,
    event_type: eventType,
    value: body.value != null ? Number(body.value) : null,
    currency: body.currency || 'BRL',
    external_ref: body.external_ref ?? null,
    metadata: body.metadata ?? {}
  }
}];

